const eyeMat=mat('#102e3d',.15);for(const x of [-.125,.125]){const eye=sphere(x,.36,.325,.064,eyeMat,ghost);eye.scale.set(.7,1.3,.35);sphere(x-.012,.379,.348,.012,materials.paper,ghost);}const cheekMat=mat('#73c3b4',.7);for(const x of [-.23,.23]){const cheek=sphere(x,.245,.295,.055,cheekMat,ghost);cheek.scale.set(1,.45,.18);}for(const x of [-.41,.41]){const arm=sphere(x,-.005,.03,.14,ghostMat,ghost);arm.scale.set(1.55,.6,.7);arm.rotation.z=x<0?-.5:.5;}
glow(0,.13,0,0xabffee,2.1,ghost);const shadow=mesh(new THREE.CircleGeometry(.48,32),new THREE.MeshBasicMaterial({color:0x07151f,transparent:true,opacity:.4,depthWrite:false}),0,.12,0,scene);shadow.rotation.x=-Math.PI/2;
// Stars, drifting motes and distant clockwork suspended in the blue hour.
const starsGeo=new THREE.BufferGeometry(),stars=[];for(let i=0;i<750;i++){let seed=Math.sin(i*144.3)*43758.5453;seed-=Math.floor(seed);const a=i*2.39996,r=19+seed*28;stars.push(Math.cos(a)*r,seed*34-7,Math.sin(a)*r);}starsGeo.setAttribute('position',new THREE.Float32BufferAttribute(stars,3));const starsMesh=new THREE.Points(starsGeo,new THREE.PointsMaterial({size:.048,color:0xa8cacf,transparent:true,opacity:.72}));scene.add(starsMesh);
const dustGeo=new THREE.BufferGeometry(),dust=[];for(let i=0;i<90;i++)dust.push(Math.sin(i*43.1)*8,1+(i%11)*.45,Math.cos(i*23.3)*8);dustGeo.setAttribute('position',new THREE.Float32BufferAttribute(dust,3));const dustMesh=new THREE.Points(dustGeo,new THREE.PointsMaterial({size:.035,color:0xe5ce91,transparent:true,opacity:.6}));scene.add(dustMesh);
