function resize(){const w=innerWidth,h=innerHeight,aspect=w/h;renderer.setSize(w,h);const halfH=(w<760?Math.max(13.4,10.2/aspect):10.4)/zoom;camera.left=-halfH*aspect;camera.right=halfH*aspect;camera.top=halfH;camera.bottom=-halfH;camera.updateProjectionMatrix();if(!state.started&&w>=760)camera.setViewOffset(w,h,-w*.067,0,w,h);else if(!state.started&&w<760)camera.setViewOffset(w,h,0,h*.15,w,h);else camera.clearViewOffset();if(state.started)$('#touch-controls').classList.toggle('hidden',!(matchMedia('(pointer:coarse)').matches||w<760));}
function updateCamera(){camera.position.set(Math.sin(orbit)*28,22,Math.cos(orbit)*28);camera.lookAt(0,1.5,0);}
buildFloor();resize();updateCamera();window.addEventListener('resize',resize);

function toast(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').classList.add('show');toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function persist(){if(!state.started||state.won)return;try{localStorage.setItem(SAVE,JSON.stringify({version:1,floor:state.floor,seals:state.seals,memories:state.memories,clues:state.clues,time:state.time,caught:state.caught,hints:state.hints,clockSolved:state.clockSolved}));}catch{}}
function playTone(freq=440,duration=.7,type='sine',volume=.08){if(!soundEnabled)return;try{audioCtx??=new (window.AudioContext||window.webkitAudioContext)();audioCtx.resume();const osc=audioCtx.createOscillator(),gain=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;gain.gain.setValueAtTime(.001,audioCtx.currentTime);gain.gain.exponentialRampToValueAtTime(volume,audioCtx.currentTime+.018);gain.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+duration);osc.connect(gain);gain.connect(audioCtx.destination);osc.start();osc.stop(audioCtx.currentTime+duration+.04);}catch{}}
function chime(){[523.25,659.25,783.99].forEach((f,i)=>setTimeout(()=>playTone(f,1.8,'sine',.07),i*150));}
function formatTime(t){return String(Math.floor(t/60)).padStart(2,'0')+':'+String(Math.floor(t%60)).padStart(2,'0');}
function objective(){if(state.clockSolved)return '走进星光之门，向钟楼告别。';if(state.floor===0)return state.seals[0]?'乘坐升降台，前往齿轮回廊。':'穿过青色薄墙，用灵视寻找宝匣线索。';if(state.floor===1)return state.seals[1]?'齿轮已经苏醒，升降台通往钟楼顶。':'避开守夜者，将齿轮调整为上、下、上。';return state.seals[2]?'转动中央钟盘，回到约定的时间。':'找到观星台的约定，敲响四声钟鸣。';}
function updateHUD(){
 $('#chapter-number').textContent=String(state.floor+1).padStart(2,'0');$('#room-title').textContent=roomNames[state.floor];$('#room-subtitle').textContent=roomDescriptions[state.floor];$('#floor-badge').textContent=(state.floor+1)+'F';$('#quest-count').textContent=state.seals.filter(Boolean).length+' / 3';$('#memory-count').textContent=state.memories.length+' / 9';$('#objective-text').textContent=objective();$('#quest-list').innerHTML=questNames.map((n,i)=>`<div class="quest-item ${state.seals[i]?'complete':i===state.floor?'current':''}"><i>${state.seals[i]?'✓':i+1}</i>${n}</div>`).join('');$$('.chapter-progress span').forEach((e,i)=>e.className=state.seals[i]?'done':i===state.floor?'active':'');
}
function startGame(fresh=false){if(saved&&!fresh){Object.assign(state,{floor:clamp(saved.floor||0,0,2),seals:Array.isArray(saved.seals)?saved.seals:[false,false,false],memories:Array.isArray(saved.memories)?saved.memories:[],clues:saved.clues||[],time:saved.time||0,caught:saved.caught||0,hints:saved.hints||0,clockSolved:!!saved.clockSolved});}state.started=true;state.paused=false;$('#intro').classList.add('hidden');$('#intro-notes').classList.add('hidden');$('#scene-label').classList.add('hidden');$('#hud').classList.remove('hidden');$('#pause').classList.remove('hidden');document.body.classList.add('playing');if(matchMedia('(pointer:coarse)').matches||innerWidth<760)$('#touch-controls').classList.remove('hidden');buildFloor();resize();persist();playTone(392,1.5);toast(saved&&!fresh?'欢迎回来，小灯。旅程从这里继续。':'WASD 飘行 · 靠近光点按 E · 青色薄墙可以用空格穿过');}
function openModal(html){held.clear();touchMove.set(0,0);walkTarget=null;pendingInteract=null;state.modal=true;modalFocus=document.activeElement;$('#modal-content').innerHTML=html;$('#modal-root').classList.remove('hidden');$('#interact-prompt').classList.add('hidden');$('#modal-close').focus();}
function closeModal(){if(state.won)return;state.paused=false;state.modal=false;$('#modal-root').classList.add('hidden');$('#modal-content').innerHTML='';modalFocus?.focus?.();}
function heading(kicker,title,body=''){return `<p class="modal-eyebrow">${kicker}</p><h2 id="modal-title">${title}</h2>${body?'<p>'+body+'</p>':''}`;}
function hintControl(hints){return '<button class="hint-button" id="puzzle-hint">需要一点提示？</button><div id="puzzle-hint-box" class="hint-box hidden"></div>';}
function bindHints(hints){let i=0;$('#puzzle-hint').onclick=()=>{state.hints++;$('#puzzle-hint-box').classList.remove('hidden');$('#puzzle-hint-box').textContent=hints[Math.min(i++,hints.length-1)];$('#puzzle-hint').textContent=i<hints.length?'再给我一点提示':'再看一次提示';persist();};}
function collectMemory(i,obj){if(state.memories.includes(i))return;state.memories.push(i);obj.visible=false;interactables=interactables.filter(x=>x.id!=='memory-'+i);chime();updateHUD();persist();openModal(heading('MEMORY '+String(i+1).padStart(2,'0')+' / 09',memories[i][0],memories[i][1])+'<p style="font-size:11px;color:#67878b">这段记忆已收录在手记中。按 J 可随时重读。</p><button id="memory-ok" class="primary">把它记在心里 <span>✧</span></button>');$('#memory-ok').onclick=closeModal;}
function completeSeal(i){if(state.seals[i])return;state.seals[i]=true;chime();updateHUD();persist();const lines=['“小灯……原来这是我的名字。” 一枚铜色齿轮落在掌心。升降台重新亮起。','那些沉默了很久的齿轮，再次开始转动。“他还在楼顶等我吗？”','最后一声钟鸣散进夜色。你终于记起那个约定，还差最后五分钟。'];openModal('<div class="success-icon">✦</div>'+heading('ECHO RESTORED',questNames[i],lines[i])+'<button id="seal-ok" class="primary">继续这段旅程 <span>✧</span></button>');$('#seal-ok').onclick=closeModal;}
function runePuzzle(){if(state.seals[0]){toast('宝匣已经打开。升降台在房间右侧等你。');return;}const symbols=['✦','☾','♧','♬'],labels=['星星','月亮','羽毛','钟声'];let values=[0,0,0];openModal(heading('THE NAMELESS BOX','封印宝匣','三个古老的符号，锁住了一个遗失的名字。点击符号转动锁盘。')+'<div class="puzzle-slots">'+values.map((_,i)=>`<button class="rune-button" data-rune="${i}"><span>✦</span><small>星星</small><span class="rune-index">0${i+1}</span></button>`).join('')+'</div><div class="puzzle-status" id="puzzle-status">哪一段故事，曾经经过这里？</div><div class="modal-actions"><button class="primary" id="rune-submit">打开宝匣 <span>◇</span></button>'+hintControl()+'</div>');$$('[data-rune]').forEach(b=>b.onclick=()=>{const i=+b.dataset.rune;values[i]=(values[i]+1)%4;b.querySelector('span').textContent=symbols[values[i]];b.querySelector('small').textContent=labels[values[i]];playTone(240+values[i]*70,.14);});$('#rune-submit').onclick=()=>{if(values.join()==='1,2,3')completeSeal(0);else{$('#puzzle-status').textContent='锁盘轻轻摇了摇头。试着按故事的顺序排列。';playTone(130,.3);}};bindHints(['青色薄墙后，藏着一段看不见的墨迹。空格穿墙，Q 开启灵视。','月亮升起，羽毛落下，钟声把名字送回家。','从左到右：月亮 → 羽毛 → 钟声。']);}
function gearPuzzle(){if(state.seals[1]){toast('传动装置运转正常，继续前往钟楼顶吧。');return;}let values=[0,0,0];openModal(heading('THE SLEEPING ENGINE','唤醒传动装置','铜牌上刻着目标：↑ ↓ ↑。拉杆会同时翻转相连的齿轮。')+'<div class="puzzle-slots" id="gear-state">'+values.map((v,i)=>`<div class="gear-dial" style="text-align:center;padding-top:13px"><span class="direction">↓</span><small>齿轮 0${i+1}</small></div>`).join('')+'</div><div class="bell-row" style="margin:12px 0"><button class="secondary" id="lever-a" style="flex:1">A · 翻转 1、2</button><button class="secondary" id="lever-b" style="flex:1">B · 翻转 2、3</button><button class="secondary" id="lever-c" style="flex:1">C · 翻转 2</button></div><div class="puzzle-status" id="puzzle-status">每次拉动，都会改变两端的命运。</div><div class="modal-actions"><button id="gear-reset" class="secondary">复位</button>'+hintControl()+'</div>');const render=()=>{$$('#gear-state .direction').forEach((el,i)=>el.textContent=values[i]?'↑':'↓');playTone(185,.2,'triangle');if(values.join()==='1,0,1')completeSeal(1);};$('#lever-a').onclick=()=>{values[0]^=1;values[1]^=1;render();};$('#lever-b').onclick=()=>{values[1]^=1;values[2]^=1;render();};$('#lever-c').onclick=()=>{values[1]^=1;render();};$('#gear-reset').onclick=()=>{values=[0,0,0];render();};bindHints(['初始方向都是向下，目标是让两边向上，中间保持向下。','A 和 B 都会翻转中间的齿轮。翻转两次，就会回到原位。','点击复位，然后分别拉动 A 和 B 一次。']);}
function bellPuzzle(){if(state.seals[2]){toast('约定的旋律已经响起。最后的钟盘在中央大钟下方。');return;}let input=[];const tones=[261.63,329.63,392];openModal(heading('A PROMISE IN FOUR NOTES','最后的钟鸣','不用追赶节奏，只要记住四声的顺序。低、中、高，哪一声会再次回来？')+'<div class="bell-row">'+['低音','中音','高音'].map((n,i)=>`<button class="bell-key" data-bell="${i}"><span style="font-size:${36-i*5}px">♧</span><small>${i+1} · ${n}</small></button>`).join('')+'</div><div class="sequence-dots">'+Array(4).fill('<i></i>').join('')+'</div><div class="puzzle-status" id="puzzle-status">等待第一声钟鸣…</div><div class="modal-actions"><button id="bell-reset" class="secondary">重新开始</button>'+hintControl()+'</div>');const refresh=()=>{$$('.sequence-dots i').forEach((e,i)=>e.classList.toggle('filled',i<input.length));};$$('[data-bell]').forEach(b=>b.onclick=()=>{const n=+b.dataset.bell;input.push(n);playTone(tones[n],1.8,'sine',.18);playTone(tones[n]*2.01,1.2,'sine',.035);b.classList.add('ringing');setTimeout(()=>b.classList.remove('ringing'),330);refresh();$('#puzzle-status').textContent=input.map(i=>['低','中','高'][i]).join(' · ');if(input.length===4){if(input.join()==='0,2,1,2')completeSeal(2);else{input=[];$('#puzzle-status').textContent='回声渐渐消失。四声旋律还没有对上，再试一次。';setTimeout(refresh,600);}}});$('#bell-reset').onclick=()=>{input=[];refresh();$('#puzzle-status').textContent='等待第一声钟鸣…';};bindHints(['观星台的记忆，记着你们之间的四声暗号。','先低音，再高音，回到中音，最后再次回到高处。','依次敲响：1 低音 → 3 高音 → 2 中音 → 3 高音。']);}
function clockPuzzle(){if(!state.seals.every(Boolean)){toast('钟盘需要三段回声。先敲响左侧的铜钟。');return;}if(state.clockSolved){toast('星光之门已打开，走近光环后按 E 告别。');return;}let hour=9,minute=0;openModal(heading('FIVE MINUTES TO MIDNIGHT','回到约定的时刻','时针与分针已经松开。那张写着约定的纸条，还留在青色薄墙后。')+'<div class="clock-display" id="clock-display">09 : 00</div><div class="time-controls"><button class="secondary" id="hour-up">时针 +1</button><button class="secondary" id="minute-up">分针 +5</button></div><div class="puzzle-status" id="puzzle-status">钟楼，等待着那个时刻。</div><div class="modal-actions"><button class="primary" id="clock-submit">让时间继续 <span>◷</span></button>'+hintControl()+'</div>');const render=()=>$('#clock-display').textContent=String(hour).padStart(2,'0')+' : '+String(minute).padStart(2,'0');$('#hour-up').onclick=()=>{hour=(hour+1)%12;render();playTone(330,.1);};$('#minute-up').onclick=()=>{minute=(minute+5)%60;render();playTone(440,.1);};$('#clock-submit').onclick=()=>{if(hour===11&&minute===55){state.clockSolved=true;makePortal();chime();updateHUD();persist();closeModal();toast('11:55。星光之门已经开启，你可以回家了。');}else $('#puzzle-status').textContent='还不是那个时刻。最后五分钟，意味着什么？';};bindHints(['青色薄墙后的隐形记忆，记录着最后的五分钟。','你们约好在午夜前五分钟见面。','把钟盘调整为 11 : 55，然后让时间继续。']);}
function elevatorMenu(){const max=state.seals[0]?(state.seals[1]?2:1):0;openModal(heading('THE OLD LIFT','去往哪一层？','升降台会记得你的脚步。可以随时回到已经开启的楼层寻找遗漏的记忆。')+'<div style="display:grid;gap:12px;margin:25px 0">'+roomNames.map((n,i)=>`<button class="secondary" data-floor="${i}" ${i>max?'disabled':''} style="display:flex;justify-content:space-between"><span>0${i+1} · ${n}</span><span>${i===state.floor?'所在楼层':i>max?'尚未开启':'前往'}</span></button>`).join('')+'</div>');$$('[data-floor]').forEach(b=>b.onclick=()=>{const floor=+b.dataset.floor;if(floor>max)return;closeModal();if(floor!==state.floor){state.floor=floor;state.energy=100;state.invincible=3;buildFloor();persist();chime();toast(roomNames[floor]);}});}
function showJournal(tab=state.floor){openModal(heading('LITTLE LIGHT’S JOURNAL','小灯的手记')+'<div class="journal-tabs">'+roomNames.map((n,i)=>`<button data-journal="${i}" class="${tab===i?'selected':''}">${i+1}F · ${['藏书室','齿轮厅','钟楼顶'][i]}</button>`).join('')+'</div>'+memories.slice(tab*3,tab*3+3).map((m,j)=>state.memories.includes(tab*3+j)?`<div class="memory-entry"><small>✧ ${m[0]}</small><p>${m[1]}</p></div>`:`<div class="memory-entry locked">◇ 尚未寻回的记忆<br><span style="font-size:11px">探索这一层，试着用灵视观察闪烁的角落。</span></div>`).join('')+'<p style="font-size:11px">记忆收集 '+state.memories.length+' / 9 · 部分碎片只有在灵视中才会显现。</p>');$$('[data-journal]').forEach(b=>b.onclick=()=>showJournal(+b.dataset.journal));}
function showHelp(){openModal(heading('A SMALL GUIDE','做一只自由的小幽灵','收集三段回声，修好午夜钟楼，寻找通往黎明的出口。')+'<div class="controls-grid"><kbd>W A S D / ↑↓←→</kbd><span>飘行；也可以点击地面前往</span><kbd>E / 点击机关</kbd><span>靠近后交互或拾取记忆</span><kbd>空格 / Shift</kbd><span>穿墙冲刺，消耗 30 灵力；可穿过青色薄墙</span><kbd>Q</kbd><span>切换灵视，显现隐藏的记忆</span><kbd>J</kbd><span>打开手记，重读已经收集的线索</span><kbd>Esc / P</kbd><span>暂停或继续，关闭解谜面板</span><kbd>拖动 / 滚轮</kbd><span>转动视角 / 缩放场景</span></div><p style="font-size:12px">灵力会自动恢复。守夜者碰到你时会将你送回安全点，已完成的谜题和记忆都会保留。每个机关都有三级提示。旅程自动保存在当前浏览器中。</p><button class="primary" id="help-ok">我准备好了 <span>✧</span></button>');$('#help-ok').onclick=closeModal;}
function togglePause(){if(state.won)return;if(state.modal){closeModal();return;}if(!state.started)return;state.paused=!state.paused;if(state.paused){persist();openModal(heading('TAKE YOUR TIME','让时间，等一等。','你的旅程已经保存。钟楼不会催促一只小幽灵。')+'<div class="modal-actions"><button class="primary" id="resume">继续旅程 <span>▷</span></button><button class="secondary" id="pause-help">操作说明</button></div>');$('#resume').onclick=()=>{state.paused=false;closeModal();};$('#pause-help').onclick=()=>{state.paused=false;showHelp();};}else closeModal();}
function finishGame(){if(!state.clockSolved)return;persist();state.won=true;chime();const perfect=state.memories.length===9;openModal('<div class="ending"><div class="success-icon">✧</div>'+heading(perfect?'THE WHOLE STORY':'UNTIL THE NEXT DAWN','小灯，天亮了。',perfect?'你终于读完了那张明信片。他早已平安到家。<br>留下来的约定，也可以在今天完成。':'钟楼再次走动，而你终于走向了星空。<br>有些告别不需要等到所有故事都有答案。')+'<div class="ending-stats"><div><b>'+formatTime(state.time)+'</b><span>这段旅程</span></div><div><b>'+state.memories.length+' / 9</b><span>寻回的记忆</span></div><div><b>'+state.caught+'</b><span>被守夜者发现</span></div></div><div class="modal-actions" style="justify-content:center"><button id="ending-continue" class="secondary">留在钟楼，继续收集</button><button id="ending-restart" class="primary">再做一个梦 <span>✦</span></button></div></div>');$('#modal-close').classList.add('hidden');$('#ending-continue').onclick=()=>{state.won=false;$('#modal-close').classList.remove('hidden');closeModal();persist();};$('#ending-restart').onclick=()=>{try{localStorage.removeItem(SAVE);}catch{}location.reload();};}
function toggleVision(){if(!state.started||state.modal||state.paused||state.won)return;state.vision=!state.vision;secretMeshes.forEach(m=>{const id=m.userData.interactId;const collected=id?.startsWith('memory-')&&state.memories.includes(+id.split('-')[1]);m.visible=state.vision&&!collected;});document.body.classList.toggle('vision-active',state.vision);$('#vision-banner').classList.toggle('hidden',!state.vision);$('#vision').classList.toggle('active',state.vision);playTone(state.vision?523:262,.45,'sine',.05);}
function blocked(x,z){if(Math.hypot(x,z)>7.3||z< -5.15||x< -6.15)return true;return colliders.some(c=>Math.abs(x-c.x)<c.w/2+.3&&Math.abs(z-c.z)<c.d/2+.3);}
function dash(){if(!state.started||state.modal||state.paused||state.won)return;if(state.energy<30){toast('灵力不足，稍等片刻，它会自动恢复。');return;}if(state.dashCooldown>0)return;const dir=moveDirection.clone().normalize();let destination=null;for(let d=3.6;d>=1;d-=.15){const p=playerPos.clone().addScaledVector(dir,d);if(!blocked(p.x,p.z)){destination=p;break;}}if(!destination){toast('这里没有安全的落脚点，试着换个方向。');return;}state.energy-=30;state.dashCooldown=1.0;state.invincible=1.2;for(let i=0;i<7;i++){const p=playerPos.clone().lerp(destination,i/7);const g=glow(p.x,1.05,p.z,0xabf7e6,1.3,scene);trail.push({mesh:g,life:.52});}playerPos.copy(destination);walkTarget=null;pendingInteract=null;playTone(180,.5,'triangle',.04);}
function interact(){if(state.modal||state.paused||!state.started||state.won)return;if(nearest){nearest.action();}else toast('靠近宝匣、光点或升降台，出现 E 时就能交互。');}
function updateInteraction(){nearest=null;let best=Infinity;for(const item of interactables){if(!item.object.visible)continue;const d=Math.hypot(item.x-playerPos.x,item.z-playerPos.z);if(d<item.r&&d<best){best=d;nearest=item;}}if(nearest&&!state.modal){$('#interact-prompt').classList.remove('hidden');$('#interact-prompt span').textContent=nearest.label;}else $('#interact-prompt').classList.add('hidden');}
function caught(){if(state.invincible>0||guardHitCooldown>0)return;state.caught++;state.energy=Math.max(10,state.energy-25);playerPos.set(1,0,4.7);state.invincible=4;guardHitCooldown=3;walkTarget=null;pendingInteract=null;playTone(110,.8,'triangle',.07);toast('被守夜者发现了！记忆还在，绕开它的暖色光圈。');persist();}

$('#start').onclick=()=>startGame();$('#new-game').onclick=()=>{saved=null;try{localStorage.removeItem(SAVE);}catch{}startGame(true);};if(saved){$('#start-label').textContent='继续未完的梦';$('#new-game').classList.remove('hidden');}
$('#sound').onclick=()=>{soundEnabled=!soundEnabled;$('.sound-slash').classList.toggle('hidden',soundEnabled);$('#sound').title=soundEnabled?'关闭声音':'开启声音';$('#sound').setAttribute('aria-label',$('#sound').title);if(soundEnabled){chime();toast('钟楼的声音已开启。');}else toast('声音已关闭。');};$('#help').onclick=showHelp;$('#pause').onclick=togglePause;$('#journal').onclick=()=>showJournal();$('#vision').onclick=toggleVision;$('#dash').onclick=dash;$('#touch-interact').onclick=interact;
$('#modal-close').onclick=()=>{state.paused=false;closeModal();};$('#modal-root').onclick=e=>{if(e.target===$('#modal-root')){state.paused=false;closeModal();}};
window.addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Tab'].includes(e.code)&&!(e.code==='Tab'&&!state.modal))e.preventDefault();if(state.modal&&e.code==='Tab'){const focusable=[...$('#modal-root').querySelectorAll('button:not([disabled]):not(.hidden)')];const i=focusable.indexOf(document.activeElement);focusable[(i+(e.shiftKey?-1:1)+focusable.length)%focusable.length]?.focus();return;}if(e.repeat)return;if(e.code==='Escape'||e.code==='KeyP'){togglePause();return;}if(e.code==='Enter'&&!state.started&&!state.modal){startGame();return;}if(state.modal||state.paused)return;held.add(e.code);if(e.code==='KeyE')interact();if(e.code==='Space'||e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(e.code==='KeyQ')toggleVision();if(e.code==='KeyJ'&&state.started)showJournal();});window.addEventListener('keyup',e=>held.delete(e.code));window.addEventListener('blur',()=>{held.clear();touchMove.set(0,0);if(state.started&&!state.modal&&!state.won&&!state.paused)togglePause();});
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2(),floorPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0),intersection=new THREE.Vector3();
$('#world').addEventListener('pointerdown',e=>{dragging=true;lastPointer={x:e.clientX,y:e.clientY};dragAmount=0;$('#world').setPointerCapture(e.pointerId);});$('#world').addEventListener('pointermove',e=>{if(!dragging||!lastPointer)return;const dx=e.clientX-lastPointer.x;dragAmount+=Math.abs(dx)+Math.abs(e.clientY-lastPointer.y);orbit-=dx*.005;lastPointer={x:e.clientX,y:e.clientY};});$('#world').addEventListener('pointerup',e=>{dragging=false;if(dragAmount>8||!state.started||state.modal||state.paused)return;pointer.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(roomGroup.children,true);const picked=hits.find(h=>h.object.userData.interactId&&h.object.visible);if(picked){const item=interactables.find(i=>i.id===picked.object.userData.interactId);if(item&&item.object.visible){if(Math.hypot(item.x-playerPos.x,item.z-playerPos.z)<item.r){item.action();return;}walkTarget=new THREE.Vector3(item.x,0,item.z);pendingInteract=item;return;}}if(raycaster.ray.intersectPlane(floorPlane,intersection)&&Math.hypot(intersection.x,intersection.z)<7.5){walkTarget=intersection.clone();pendingInteract=null;}});$('#world').addEventListener('wheel',e=>{e.preventDefault();zoom=clamp(zoom-e.deltaY*.0007,.8,1.3);resize();},{passive:false});
const joy=$('#joystick'),knob=$('#joystick-knob');let joyActive=false;function joystickUpdate(e){const rect=joy.getBoundingClientRect();let x=e.clientX-rect.left-52,y=e.clientY-rect.top-52;const len=Math.hypot(x,y);if(len>35){x=x/len*35;y=y/len*35;}knob.style.transform=`translate(${x}px,${y}px)`;touchMove.set(x/35,-y/35);walkTarget=null;}
joy.onpointerdown=e=>{joyActive=true;joy.setPointerCapture(e.pointerId);joystickUpdate(e);};joy.onpointermove=e=>{if(joyActive)joystickUpdate(e);};joy.onpointerup=joy.onpointercancel=()=>{joyActive=false;touchMove.set(0,0);knob.style.transform='';};
function registerAgentTools(){const ctx=document.modelContext;if(!ctx?.registerTool)return;const abort=new AbortController();const register=tool=>{try{Promise.resolve(ctx.registerTool(tool,{signal:abort.signal})).catch(()=>{});}catch{}};register({name:'read_clocktower_progress',description:'Read the current visible game progress, objective and collected memories.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments are accepted.');return {started:state.started,floor:state.floor+1,room:roomNames[state.floor],seals:[...state.seals],memories:state.memories.map(i=>memories[i][0]),objective:objective(),won:state.won};}});register({name:'open_clocktower_journal',description:'Open the game journal for a floor, showing only memories already collected by the player.',inputSchema:{type:'object',properties:{floor:{type:'integer',minimum:1,maximum:3}},required:['floor'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!Number.isInteger(input.floor)||input.floor<1||input.floor>3||Object.keys(input).some(k=>k!=='floor'))throw Error('floor must be an integer from 1 to 3.');if(!state.started||state.won)throw Error('Start or resume the game first.');showJournal(input.floor-1);return {opened:true,floor:input.floor};}});addEventListener('pagehide',()=>abort.abort(),{once:true});}
registerAgentTools();
// A small read-only diagnostic surface supports reproducible integration checks.
window.hollowHour={getState:()=>({...state,position:{x:playerPos.x,z:playerPos.z},nearby:nearest?.id??null,objects:interactables.filter(i=>i.object.visible).map(i=>({id:i.id,x:i.x,z:i.z}))}),renderer};
let elapsed=0,last=performance.now(),saveElapsed=0,ambientElapsed=0;
function animate(now){requestAnimationFrame(animate);const dt=Math.min((now-last)/1000,.045);last=now;elapsed+=dt;const active=state.started&&!state.paused&&!state.modal&&!state.won;
 if(active){state.time+=dt;state.energy=Math.min(100,state.energy+dt*8);state.dashCooldown=Math.max(0,state.dashCooldown-dt);state.invincible=Math.max(0,state.invincible-dt);guardHitCooldown=Math.max(0,guardHitCooldown-dt);const right=new THREE.Vector3(Math.cos(orbit),0,-Math.sin(orbit)),forward=new THREE.Vector3(-Math.sin(orbit),0,-Math.cos(orbit));let ix=(held.has('KeyD')||held.has('ArrowRight')?1:0)-(held.has('KeyA')||held.has('ArrowLeft')?1:0)+touchMove.x,iy=(held.has('KeyW')||held.has('ArrowUp')?1:0)-(held.has('KeyS')||held.has('ArrowDown')?1:0)+touchMove.y;let direction=new THREE.Vector3();if(ix||iy){walkTarget=null;pendingInteract=null;direction.addScaledVector(right,ix).addScaledVector(forward,iy);}else if(walkTarget){direction.copy(walkTarget).sub(playerPos);direction.y=0;if(pendingInteract&&direction.length()<pendingInteract.r*.98){const action=pendingInteract.action;walkTarget=null;pendingInteract=null;direction.set(0,0,0);action();}else if(direction.length()<.16){walkTarget=null;pendingInteract=null;direction.set(0,0,0);}}
 if(direction.lengthSq()>.01){direction.normalize();moveDirection.copy(direction);let nx=playerPos.x+direction.x*dt*3.4,nz=playerPos.z+direction.z*dt*3.4;const before=playerPos.clone();if(!blocked(nx,playerPos.z))playerPos.x=nx;if(!blocked(playerPos.x,nz))playerPos.z=nz;if(before.distanceTo(playerPos)<.001&&walkTarget){walkTarget=null;pendingInteract=null;toast('前方被挡住了。换条路线，或面向障碍按空格穿过。');}let targetRot=Math.atan2(direction.x,direction.z);ghost.rotation.y+=Math.atan2(Math.sin(targetRot-ghost.rotation.y),Math.cos(targetRot-ghost.rotation.y))*.14;}
 for(const g of guards){const t=state.time*.42+g.phase;g.group.position.set(Math.cos(t)*4.1,Math.sin(elapsed*2)*.1,Math.sin(t)*2.8+1);g.group.rotation.y=-t;const dangerous=!state.clockSolved;g.group.visible=dangerous;if(dangerous&&Math.hypot(g.group.position.x-playerPos.x,g.group.position.z-playerPos.z)<.9)caught();}
 updateInteraction();saveElapsed+=dt;if(saveElapsed>5){persist();saveElapsed=0;}ambientElapsed+=dt;if(ambientElapsed>9){ambientElapsed=0;playTone([130.81,164.81,196][Math.floor(elapsed/9)%3],4,'sine',.018);}}
 if(!state.started){ghost.rotation.y=.4+Math.sin(elapsed*.3)*.3;ghost.position.set(1.2,1.15+Math.sin(elapsed*2)*.13,3.5);}
 else{ghost.position.set(playerPos.x,1.0+Math.sin(elapsed*2.7)*.105,playerPos.z);ghost.visible=!(state.invincible>0&&Math.floor(elapsed*10)%3===0);}
 shadow.position.set(ghost.position.x,.11,ghost.position.z);const s=1-Math.sin(elapsed*2.7)*.08;shadow.scale.set(s,s,s);cyanLight.position.set(ghost.position.x,2,ghost.position.z);
 for(const gear of gears)gear.group.rotation.z+=dt*gear.speed*(state.seals[1]?2.4:.65);
 for(const f of floaters){if(f.kind==='memory'){f.mesh.position.y=f.base+Math.sin(elapsed*1.8+f.mesh.position.x)*.15;f.mesh.rotation.y+=dt*.55;}else if(f.kind==='pendulum'){f.mesh.rotation.z=Math.sin(elapsed*1.6)*.11;f.disk.position.x=-.7+Math.sin(elapsed*1.6)*.13;}}
 flames.forEach((f,i)=>{f.scale.y=1.7+Math.sin(elapsed*8+i*2)*.2;});for(let i=trail.length-1;i>=0;i--){trail[i].life-=dt;trail[i].mesh.material.opacity=Math.max(0,trail[i].life/.52)*.65;if(trail[i].life<=0){scene.remove(trail[i].mesh);trail[i].mesh.material.dispose();trail.splice(i,1);}}
 if(state.clockSolved&&clockHands.length){clockHands[0].rotation.z=-Math.PI*2*(11+55/60)/12;clockHands[1].rotation.z=-Math.PI*2*55/60;}if(portal){portal.children[0].rotation.z=Math.sin(elapsed*.5)*.03;portal.children[1].material.opacity=.7+Math.sin(elapsed*2)*.13;}
 dustMesh.rotation.y=elapsed*.014;starsMesh.rotation.y=elapsed*.0008;$('#energy-fill').style.width=state.energy+'%';$('#energy-value').textContent=Math.floor(state.energy);$('#ability-status').textContent=state.dashCooldown>0?'灵体正在重新凝聚…':state.energy<30?'灵力恢复中…':'安静地靠近，勇敢地穿过。';$('#timer').textContent=formatTime(state.time);$('#dash').style.opacity=state.energy<30||state.dashCooldown>0?'.45':'1';updateCamera();renderer.render(scene,camera);
}
requestAnimationFrame(animate);setTimeout(()=>{$('#loading').style.opacity='0';setTimeout(()=>$('#loading').remove(),650);},450);
